package com.nusadb.hibernate;

import org.hibernate.dialect.identity.IdentityColumnSupportImpl;

/**
 * {@code GenerationType.IDENTITY} as a {@code GENERATED BY DEFAULT AS IDENTITY} column. The new key
 * is read back through {@code getGeneratedKeys()}, which the driver answers with an
 * {@code INSERT ... RETURNING}.
 */
final class NusaIdentityColumnSupport extends IdentityColumnSupportImpl {

    static final NusaIdentityColumnSupport INSTANCE = new NusaIdentityColumnSupport();

    private NusaIdentityColumnSupport() {}

    @Override
    public boolean supportsIdentityColumns() {
        return true;
    }

    @Override
    public boolean hasDataTypeInIdentityColumn() {
        return true;
    }

    @Override
    public String getIdentityColumnString(int type) {
        return "generated by default as identity";
    }
}
